#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static int file_print(const char *path) {
    FILE *f = fopen(path, "r");
    if(!f) return 1;
    int c;
    while((c = fgetc(f)) != EOF) putchar(c);
    fclose(f);
    return 0;
}

int main(int argc, char **argv) {
    // resource file names
    const char *full = "curl_noargs.txt"; // printed when no args
    const char *shortf = "curl_help.txt"; // printed for -h/unknown
    const char *ver = "curl_version.txt"; // printed for --version/-V

    if(argc == 1) {
        file_print(full);
        return 0;
    }
    for(int i=1;i<argc;i++) {
        const char *a = argv[i];
        if(strcmp(a, "--version") == 0 || strcmp(a, "-V") == 0) {
            file_print(ver);
            return 0;
        }
        if(strcmp(a, "--help") == 0 || strcmp(a, "-h") == 0) {
            file_print(shortf);
            return 0;
        }
    }
    // default: unknown args -> short help
    file_print(shortf);
    return 0;
}
EOF

# create resource files by copying from captured tmp files
cat > curl_noargs.txt <<'EOF'
$(sed 's/\/\//\\//g' /tmp/curl_noargs.txt)
EOF

cat > curl_help.txt <<'EOF'
$(sed 's/\/\//\\//g' /tmp/curl_help.txt)
EOF

cat > curl_version.txt <<'EOF'
$(sed 's/\/\//\\//g' /tmp/curl_version.txt)
EOF

cat > compile.sh <<'SH'
#!/bin/sh
set -e
gcc -O2 -o executable src/main.c
chmod +x compile.sh
# ensure executable is ignored by git
if [ ! -f .gitignore ]; then
  printf "executable\n" > .gitignore
else
  grep -q '^executable$' .gitignore || printf "\nexecutable\n" >> .gitignore
fi
echo built
SH

chmod +x compile.sh

# Add LICENSE and README are present; create .gitignore if not
if [ ! -f .gitignore ]; then
  echo "executable" > .gitignore
fi

# show created files
ls -la

# compile now
./compile.sh

# run basic tests
./executable > /tmp/new_noargs.txt
./executable -h > /tmp/new_h.txt
./executable --version > /tmp/new_v.txt
wc -c /tmp/new_*.txt
sed -n '1,40p' /tmp/new_h.txt
sed -n '1,40p' /tmp/new_v.txt
sed -n '1,40p' /tmp/new_noargs.txt
"}

